import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  // --- No Sphinx present: only Sphinx cards produce points ---
  it.todo("scores an empty army as 0");
  it.todo("scores an army with no Sphinx as 0 — a lone hydra is worth 0");
  it.todo(
    "scores an army of many non-Sphinx monsters as 0 — hydra, zombie, cyclops, orthrus is worth 0",
  );

  // --- A single Sphinx, three or fewer distinct types: 1 point each ---
  it.todo("scores a lone Sphinx as 1 — one type is not beyond three");
  it.todo("scores a Sphinx with two distinct types as 1 — sphinx, hydra is worth 1");
  it.todo(
    "scores a Sphinx with exactly three distinct types as 1 — sphinx, hydra, zombie is worth 1",
  );

  // --- A single Sphinx, more than three distinct types: 2 per type beyond three ---
  it.todo(
    "scores a Sphinx with four distinct types as 2 — sphinx, hydra, zombie, cyclops is worth 2",
  );
  it.todo(
    "scores a Sphinx with five distinct types as 4 — sphinx, hydra, zombie, cyclops, orthrus is worth 4",
  );
  it.todo(
    "scores a Sphinx with all seven distinct types as 8 — four types beyond three is worth 8",
  );

  // --- Duplicates do not add types ---
  it.todo(
    "counts a repeated monster as a single type — sphinx, hydra, hydra, zombie is worth 1",
  );

  // --- Undead Warrior ranks are distinct types ---
  it.todo(
    "counts each Undead Warrior rank as its own type — sphinx, undead-warrior rank 1, rank 2, rank 3 is worth 2",
  );
  it.todo(
    "counts two Undead Warriors of the same rank as one type — sphinx, undead-warrior rank 2, rank 2, hydra is worth 1",
  );

  // --- Multiple Sphinxes each score ---
  it.todo("scores two Sphinxes with three or fewer types as 2 — 1 point each");
  it.todo(
    "scores two Sphinxes with five distinct types as 8 — 4 points each",
  );

  // --- Integration example from the spec ---
  it.todo(
    "scores the spec example — sphinx, undead-warrior rank 2, hydra is worth 1",
  );
});

